      const recent = list.slice(0, 5);
      updatesList.innerHTML = '';
      recent.forEach(text => {
        const li = document.createElement('li');
        li.textContent = text;
        updatesList.appendChild(li);
      });

      // Wire up copy button
      if (copyBtn) {
