          showMsg('download-updates-msg', 'Downloaded!');
        });
      }

      // Wire up download CSV button
      if (downloadCsvBtn) {
        downloadCsvBtn.addEventListener('click', () => {
          try {
            const rows = [['index', 'tweak']];
            list.forEach((text, i) => {
